package com.foodsupply.management.distribution.service;
import com.foodsupply.management.common.exception.ResourceNotFoundException;import com.foodsupply.management.distribution.dto.DistributionPlanRequest;import com.foodsupply.management.distribution.entity.DistributionPlan;import com.foodsupply.management.distribution.repository.DistributionPlanRepository;import org.springframework.stereotype.Service;import java.util.List;
@Service public class DistributionPlanService {private final DistributionPlanRepository repository;public DistributionPlanService(DistributionPlanRepository r){repository=r;}
 public List<DistributionPlan> findAll(){return repository.findAll();}public DistributionPlan findById(Long id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Distribution plan",id));}
 public DistributionPlan create(DistributionPlanRequest r){return repository.save(map(new DistributionPlan(),r));}public DistributionPlan update(Long id,DistributionPlanRequest r){return repository.save(map(findById(id),r));}public void delete(Long id){repository.delete(findById(id));}
 private DistributionPlan map(DistributionPlan p,DistributionPlanRequest r){p.setBeneficiaryId(r.beneficiaryId());p.setFoodItemId(r.foodItemId());p.setQuantity(r.quantity());p.setDistributionCentreId(r.distributionCentreId());p.setPlannedDate(r.plannedDate());if(r.status()!=null)p.setStatus(r.status());return p;}}
